use super::*;
#[path="../examples/support/reference_hierarchy.rs"]mod reference_hierarchy;
use std::{path::Path,sync::Arc,io};use crate::policy_body_demand::PolicyFailure;
struct Source(dm_preprocess::AcquiredSource);
impl dm_preprocess::SourceProvider for Source{fn read(&self,_:&Path)->Result<String,String>{Err("actual original bytes required".into())}fn acquired_source(&self,_:&Path)->Result<Option<dm_preprocess::AcquiredSource>,String>{Ok(Some(self.0.clone()))}fn source_acquisition(&self,_:&Path,text:&dm_preprocess::SourceText)->Option<dm_preprocess::AcquiredSource>{self.0.lease().source_text().same_view(text).then(||self.0.clone())}}
fn inputs(source:&str,certified:bool)->(std::path::PathBuf,PolicyInputs){use crate::policy_inputs::{HostCapture,PolicyRole};let root=std::env::current_dir().unwrap().join("engine-actual-body-fixture");let seed=reference_hierarchy::seed();let provider=Source(dm_preprocess::AcquiredSource::from_original_bytes(source.as_bytes().to_vec(),()));let executor=dm_exec::BuildExecutor::new(1).unwrap();let front=dm_tree::frontend::build_with_executor_and_semantic_state_for_policy(&root.join("code/engine/probe.dm"),&provider,&Default::default(),dm_tree::frontend::FrontendConfig{workers:1,engine:certified.then_some(&seed),observer:None},None,&executor,None,true).unwrap();let raw=front.files.iter().filter(|f|f.captured).map(|f|HostCapture::analyze_raw(Arc::clone(&f.path),PolicyRole::DmSource,{let raw=f.text.replace("\r\n","\n").replace('\r',"\n");if raw==f.text.as_str(){f.text.clone()}else{raw.into()}})).collect::<Vec<_>>();(root,PolicyInputs::capture(&front,raw).unwrap())}
struct Work{left:usize,polls:usize,fail_at:usize}
impl WorkspaceWork for Work{type Error=PolicyFailure;const CHECKED:bool=true;fn checkpoint(&mut self)->Result<(),PolicyFailure>{self.polls+=1;if self.polls==self.fail_at{Err(PolicyFailure::Operational(io::Error::from_raw_os_error(1450)))}else{Ok(())}}fn retain(&mut self,n:usize)->Result<(),PolicyFailure>{self.left=self.left.checked_sub(n).ok_or_else(||PolicyFailure::Operational(io::ErrorKind::OutOfMemory.into()))?;Ok(())}fn temporary(&mut self,n:usize)->Result<(),PolicyFailure>{if n>self.left{return Err(PolicyFailure::Operational(io::ErrorKind::OutOfMemory.into()))}Ok(())}fn overflow(&mut self)->PolicyFailure{PolicyFailure::Operational(io::ErrorKind::OutOfMemory.into())}fn allocation_failed(&mut self)->PolicyFailure{self.overflow()}fn body<'a>(&mut self,a:&'a dm_tree::frontend::BodyArchive,n:usize)->Result<dm_tree::frontend::ArchivedBody<'a>,PolicyFailure>{self.checkpoint()?;a.parse_checked(n).map_err(|e|match e{dm_tree::frontend::BodySyntaxFailure::Operational(e)=>PolicyFailure::Operational(e),dm_tree::frontend::BodySyntaxFailure::Syntax(e)=>Unsupported(e.message).into()})}}
fn work()->Work{Work{left:64*1024*1024,polls:0,fail_at:usize::MAX}}
fn body(input:&PolicyInputs,name:&str)->usize{let a=input.archive();a.occurrences().iter().position(|b|a.tree().member(b.member).and_then(|m|a.tree().symbols().text(m.name))==Some(name)).unwrap()}
fn observed(model:&Model<'_>,ordinal:usize,w:&mut Work)->Result<Vec<(u32,String)>,PolicyFailure>{let mut out=Vec::new();observe_body_using(model,ordinal,w,&mut|file,line,event,_|{assert_eq!(file,"code/engine/probe.dm");let text=match event{Use::Type(t)=>format!("type:{t}"),Use::Method{owner,name}=>format!("method:{owner}::{name}"),Use::Global(name)=>format!("global:{name}")};out.push((line,text));Ok(())})?;Ok(out)}
#[test]fn original_engine_receiver_rules_discard_calls_groups_indexes_and_constructor_targets(){
 let source="/datum/target/proc/run()\n    return\n/datum/holder\n    var/datum/target/member\n/datum/holder/proc/make()\n    return new /datum/target\n/datum/holder/proc/probe(datum/target/typed)\n    member.run()\n    make().run()\n    (typed).run()\n    typed[1].run()\n    new /datum/target(unvisited())\n    typed::run(ignored())\n";let(root,input)=inputs(source,true);let model=Model::new(&input,&root).unwrap();let rows=observed(&model,body(&input,"probe"),&mut work()).unwrap();assert!(rows.iter().any(|(line,s)|*line==8&&s=="method:/datum/target::run"));assert!(rows.iter().any(|(line,s)|*line==9&&s=="method:/datum/holder::make"));assert!(!rows.iter().any(|(line,s)|(9..=11).contains(line)&&s=="method:/datum/target::run"));assert!(rows.iter().any(|(line,s)|*line==12&&s=="global:unvisited"));assert!(!rows.iter().any(|(_,s)|s=="global:ignored"));assert!(rows.iter().any(|(line,s)|*line==13&&s=="method:/datum/target::run"));
}
#[test]fn engine_cstyle_init_and_increment_precede_test_with_temporal_typed_locals(){
 let source="/datum/first\n/datum/second\n/datum/holder/proc/probe()\n    for(var/datum/first/local = init_call(); test_call(); inc_call())\n        var/datum/second/later\n        later.method()\n";let(root,input)=inputs(source,true);let model=Model::new(&input,&root).unwrap();let rows=observed(&model,body(&input,"probe"),&mut work()).unwrap();let calls=rows.iter().filter(|(_,s)|s.starts_with("global:")).map(|(_,s)|s.as_str()).collect::<Vec<_>>();assert_eq!(calls,["global:init_call","global:inc_call","global:test_call"]);assert!(rows.iter().any(|(line,s)|*line==4&&s=="type:/datum/first"));assert!(rows.iter().any(|(line,s)|*line==5&&s=="type:/datum/second"));
}
#[test]fn selected_callable_uses_original_winner_and_current_header_not_old_source_alias(){
 let(root,input)=inputs("/datum/holder/proc/helper()\n    return\n/datum/holder/helper()\n    return\n/datum/holder/proc/probe()\n    helper()\n",true);let model=Model::new(&input,&root).unwrap();let mut w=work();let call=model.method("/datum/holder","helper",&mut w).unwrap().unwrap();assert!(matches!(call,CallableFact::Source{..}));assert_eq!(model.callable_file(&call,&mut w).unwrap().as_deref(),Some("code/engine/probe.dm"));let mut count=0;model.method_declaration_files("/datum/holder","helper",&mut w,&mut|_,_|{count+=1;Ok(true)}).unwrap();assert_eq!(count,2);
 let(_,foreign)=inputs("/datum/other\n",true);let other=Model::new(&foreign,&root).unwrap();assert!(other.callable_file(&call,&mut w).is_err());
}
#[test]fn engine_body_typed_inner_control_preserves_first_io_quota_and_recovers(){
 let source=format!("/datum/holder/proc/probe()\n{}","    helper()\n".repeat(2000));let(root,input)=inputs(&source,true);let model=Model::new(&input,&root).unwrap();let ordinal=body(&input,"probe");let mut failed=work();failed.fail_at=1450;assert!(matches!(observed(&model,ordinal,&mut failed),Err(PolicyFailure::Operational(e))if e.raw_os_error()==Some(1450)));assert_eq!(failed.polls,1450);let mut tiny=work();tiny.left=1;assert!(matches!(observed(&model,ordinal,&mut tiny),Err(PolicyFailure::Operational(e))if e.kind()==io::ErrorKind::OutOfMemory));assert!(!observed(&model,ordinal,&mut work()).unwrap().is_empty());
 let(root,unissued)=inputs("/datum/holder/proc/probe()\n    helper()\n",false);assert!(Model::new(&unissued,&root).is_err());
}
